class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def mergeTwoLists(list1, list2):
    # list1 / list2 为两条升序链表的头节点（ListNode），返回合并后的头节点

    if list1 == None:
        return list2
    if list2 == None:
        return list1

    answer = ListNode()
    if list1.val < list2.val:
        answer.val = list1.val
        list1 = list1.next
    else:
        answer.val =list2.val
        list2 = list2.next
    tmp = answer
    while list1 and list2:
        if list1.val < list2.val:
            new = ListNode()
            new.val = list1.val
            new.next = None
            tmp.next = new
            tmp = tmp.next
            list1 = list1.next
        else:
            new = ListNode()
            new.val = list2.val
            new.next = None
            tmp.next = new
            tmp = tmp.next
            list2 = list2.next
    if list1 == None:
        tmp.next = list2
    else:
        tmp.next = list1
    return answer    
    pass

