    # 判断括号字符串 s 是否有效，返回 True / False
    match_s = {')':'(', ']':'[', '}':'{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        else:
            if len(stack) == 0 or stack[-1] != match_s[ch]: #初始没有左括号或者不能匹配 倒着消掉
                return False
            stack.pop()#出栈

    return len(stack) == 0 #有无消除干净
