def searchInsert(nums, target):
    # 返回目标值下标，或它应按顺序插入的位置（整数）
    left = 0
    right = len(nums)-1
    if nums[right] == target:
        return right
    mid = int((left + right)/2)

    if nums[mid] == target:
        return mid

    if nums[left] > target:
        return 0

    if nums[right] < target:
        return len(nums)

    while nums[mid] != target:
        if nums[mid] > target:
            right = mid - 1
            # if (right - left) == 1:
            #    return right
            if right == left:
                return right + 1
        else:
            left = mid + 1
            if (right - left) == 1:
                return left


        mid = int((left + right) / 2)

    return mid
